// canonicalGuardPath is a second absolute-then-symlink-resolved derivation this fixture
// plants outside internal/canonicalpath — the red the owner check exists to raise.
func canonicalGuardPath(path string) string {
	abs, err := filepath.Abs(path)
	if err != nil {
		return path
	}
	if resolved, err := filepath.EvalSymlinks(abs); err == nil {
		abs = resolved
	}
	return filepath.Clean(abs)
}
